<script lang="ts">
  import { auth } from '$lib/stores/auth'; import { goto } from '$app/navigation'; import { onMount } from 'svelte';
  let username=$state(''); let password=$state(''); let error=$state(''); let loading=$state(false);
  onMount(()=>{auth.init();if($auth.isAuthenticated)goto('/dashboard')});
  async function handleSubmit(e:Event){e.preventDefault();error='';loading=true;const result=await auth.login(username,password);if(result.success)goto('/dashboard');else error=result.error||'No se pudo iniciar sesión';loading=false}
</script>
<svelte:head><title>Iniciar sesión · DocuTrust</title></svelte:head>
<div class="auth-layout"><div class="auth-aside"><span class="aside-mark anim-pop">✓</span><p class="eyebrow anim-rise">Acceso seguro</p><h1 class="anim-rise d1">Tus documentos,<br><em>bajo control.</em></h1><p class="anim-rise d2">Firma y verifica archivos con evidencia criptográfica en cada paso.</p><div class="aside-points anim-rise d3"><span>✓ Claves privadas protegidas</span><span>✓ Historial de versiones</span></div></div><section class="auth-card anim-pop"><div class="mobile-brand">DocuTrust</div><span class="eyebrow">Bienvenido de vuelta</span><h2>Iniciar sesión</h2><p class="intro">Ingresa tus credenciales para continuar.</p>{#if error}<div class="alert error anim-shake" role="alert">⚠ {error}</div>{/if}<form onsubmit={handleSubmit}><label for="username">Usuario<input id="username" type="text" bind:value={username} placeholder="Tu nombre de usuario" required disabled={loading} autocomplete="username"></label><label for="password">Contraseña<input id="password" type="password" bind:value={password} placeholder="Tu contraseña" required disabled={loading} autocomplete="current-password"></label><button class="submit btn-anim" class:is-loading={loading} type="submit" disabled={loading}>{loading?'Validando…':'Iniciar sesión'} <span>→</span></button></form><p class="switch">¿Aún no tienes una cuenta? <a href="/register">Crear cuenta</a></p><details class="anim-fade d5"><summary>Usuarios de demostración</summary><div class="demo"><code>admin</code><span>Admin123!@#</span><code>carlos</code><span>Carlos123!@#</span></div></details></section></div>
