e-columns:1fr 1fr;gap:8px;margin-top:12px;background:#f8fafc;padding:11px;border-radius:8px}.demo code{color:#4338ca;font-size:.7rem}.demo span{font-size:.7rem;color:#475569}@media(max-width:760px){.auth-layout{grid-template-columns:1fr;max-width:470px}.auth-aside{display:none}.mobile-brand{display:block;color:#4f46e5;font-weight:900;margin-bottom:25px}}@media(max-width:500px){.auth-layout{padding:12px 0}.auth-card{padding:25px 20px}}
